async function pressCommit() {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const visible = (el) => !!el && el.offsetParent !== null && el.getBoundingClientRect().width > 0;
  const bar = [...document.querySelectorAll('input[type=submit],input[type=button]')].filter((b) => visible(b) && !/_pc/.test(b.id));
  const byLabel = (label) => bar.find((b) => new RegExp(`^${label}$`, 'i').test(b.value.trim()));
  const commit = byLabel('submit') || byLabel('save');
  if (!commit) return { state: 'error', message: 'neither a Submit nor a Save button was found on the InterLink form.' };
  commit.click();
  window.__nxSaveBtn = commit.name || commit.id;
  for (let i = 0; i < 10; i++) {                                     // confirm boxes ("Are you sure?") when InterLink shows one
    await sleep(500);
    const byId = ['UF1_ButtonBar1_pcConfirmOkCancel_ASPxConfirmOk', 'UF1_PopupYesNoCancel1_pcYesNoCancel_btnPopupYNCYes'].map((id) => document.getElementById(id)).find(visible);
    const byText = [...document.querySelectorAll('input[type=submit],input[type=button],a')].find((b) => visible(b) && /^(ok|yes)$/i.test((b.value || b.textContent || '').trim()));
    const ok = byId || byText;
    if (ok) { ok.click(); break; }
  }
  return { state: 'posting', button: commit.value };
}
async function forceSave() {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const btn = document.getElementById('UF1_ButtonBar1_ASPxButton_1') || [...document.querySelectorAll('input[type=submit],input[type=button]')].find((b) => /^save$/i.test((b.value || '').trim()));
  if (!btn) return { state: 'error', message: 'the Save button could not be found to press it again.' };
  try { if (typeof __doPostBack === 'function' && btn.name) __doPostBack(btn.name, ''); else btn.click(); } catch (e) { btn.click(); }
  for (let i = 0; i < 6; i++) {
    await sleep(500);
    const ok = [...document.querySelectorAll('input[type=submit],input[type=button],a')].find((b) => b.offsetParent !== null && /^(ok|yes)$/i.test((b.value || b.textContent || '').trim()));
    if (ok) { ok.click(); break; }
  }
  return { state: 'posting' };
}
function checkSubmitted() {
  const errs = [...document.querySelectorAll('.dxeErrorCell,.dxeErrorFrame td,[id*="ErrorMessage" i],.validation-summary-errors')]
    .filter((e) => e.offsetParent !== null && e.textContent.trim());
  if (errs.length) return { ok: false, message: errs.map((e) => e.textContent.trim()).slice(0, 3).join('; ') };
  // There is no reliable "still editing" signal that holds across form variants (some have no Submit button at all,
  // so its disappearance can't be used as a success marker). Absence of a validation error is treated as success;
  // the NEXUS-L side asks the user to confirm the Job Status afterward rather than claiming certainty here.
  return { ok: true };
}

/** On InterLink's search grid: finds the application's row and reads its Report No., Report Issue Date and Job Status. */
async function readGridRow(appNo) {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const visible = (el) => !!el && el.offsetParent !== null && el.getBoundingClientRect().width > 0;
  const header = [...document.querySelectorAll('*')].find((el) => el.children.length === 0 && el.textContent.trim() === 'Application No.' && visible(el));
  if (!header) return { state: 'error', message: 'the InterLink search grid was not found.' };
  const hr = header.getBoundingClientRect();
  const inp = [...document.querySelectorAll('input[type=text]')].filter(visible).reduce((best, f) => {
    const r = f.getBoundingClientRect();
    if (r.top <= hr.top) return best;
    const dx = Math.abs(r.left - hr.left);
    return (dx < 40 && (!best || dx < best.dx)) ? { f, dx } : best;
  }, null);
  if (!inp) return { state: 'error', message: 'the Application No. search box was not found.' };
  inp.f.focus();
  inp.f.value = appNo;
  inp.f.dispatchEvent(new Event('input', { bubbles: true }));
  ['keydown', 'keypress', 'keyup'].forEach((t) => inp.f.dispatchEvent(new KeyboardEvent(t, { bubbles: true, key: 'Enter', keyCode: 13, which: 13 })));
  let row = null;
  for (let i = 0; i < 30 && !row; i++) {
    await sleep(500);
    const cell = [...document.querySelectorAll('td.dxgv')].find((td) => td.textContent.trim() === appNo);
    row = cell && cell.closest('tr');
  }
  if (!row) return { state: 'ok', found: false };
  const at = (label) => {
    const h = [...document.querySelectorAll('td.dxgvHeader, tr.dxgvHeader td')].find((x) => x.innerText.trim() === label);
    if (!h) return '';
    const hx = h.getBoundingClientRect();
    const c = [...row.querySelectorAll('td')].find((td) => { const r = td.getBoundingClientRect(); const cx = r.left + r.width / 2; return cx >= hx.left && cx <= hx.right; });
    return c ? c.innerText.trim() : '';
  };
  return { state: 'ok', found: true, reportNo: at('Report No.'), issueDate: at('Report Issue Date'), status: at('Job Status'), result: at('Overall Result') };
}

/** The messages InterLink shows in a pop-up bubble (a "toast") after Save, e.g. "A report with the entered report number has already exists!". */
function readNotices() {
  const visible = (el) => !!el && el.offsetParent !== null && el.getBoundingClientRect().width > 0;
  const word = /(already exist|has already|duplicate|invalid|cannot|can not|unable|error|failed|not allowed|is required|must be)/i;
  const out = [];
  for (const el of document.querySelectorAll('body *')) {
    if (el.children.length > 2 || !visible(el)) continue;
    const t = (el.innerText || '').replace(/\s+/g, ' ').trim();
    if (t.length < 12 || t.length > 220 || !word.test(t)) continue;
    // a bubble floats over the page: it, or something around it, is fixed or absolutely placed
    let p = el, floating = false;
    for (let i = 0; i < 6 && p && !floating; i++, p = p.parentElement) {
      const pos = getComputedStyle(p).position;
      floating = (pos === 'fixed' || pos === 'absolute') && p.getBoundingClientRect().width < 700;
    }
    if (floating && !out.includes(t)) out.push(t);
  }
  return out.slice(0, 5);
}

  return { gridProbe, goToGridFromHome, searchAndOpenUpload, fillAndAttach, pressCommit, forceSave, checkSubmitted, readGridRow, readNotices };
